import { and, eq, gt, isNull, like, ne } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { newId } from "@/lib/id";
import { uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizationSlugRetirements, organizations } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/**
 * The earliest `retired_at` that still holds its slug. A retirement stamped at
 * or before this instant has been released; one stamped later is still held.
 * ISO-8601 strings in the same format compare in time order, so the column can
 * be filtered with a plain `>`.
 */
function holdCutoff(now: Date = new Date()): string {
  return toIsoTimestamp(new Date(now.getTime() - ORG_SLUG_HOLD_DAYS * MS_PER_DAY));
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

/**
 * Resolves a slug to its workspace: the current slug first, then a slug the
 * workspace retired within the hold. Every slug-to-workspace lookup goes
 * through here so an old URL resolves the same way everywhere.
 */
export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const retired = getDb()
    .select({ org: organizations })
    .from(organizationSlugRetirements)
    .innerJoin(
      organizations,
      eq(organizations.id, organizationSlugRetirements.orgId),
    )
    .where(
      and(
        eq(organizationSlugRetirements.slug, slug),
        gt(organizationSlugRetirements.retiredAt, holdCutoff()),
        isNull(organizations.archivedAt),
      ),
    )
    .get();
  return retired ? toOrganization(retired.org) : null;
}

/**
 * Whether `slug` may become `orgId`'s current slug. Taken if another workspace
 * (live or deleted) currently holds it, or another workspace holds it retired
 * within the hold. The workspace's own retirements never block it.
 */
export async function isOrgSlugAvailable(
  slug: string,
  orgId: OrgId,
): Promise<boolean> {
  const holder = getDb()
    .select({ id: organizations.id })
    .from(organizations)
    .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
    .get();
  if (holder) return false;

  const retired = getDb()
    .select({ id: organizationSlugRetirements.id })
    .from(organizationSlugRetirements)
    .where(
      and(
        eq(organizationSlugRetirements.slug, slug),
        ne(organizationSlugRetirements.orgId, orgId),
        gt(organizationSlugRetirements.retiredAt, holdCutoff()),
      ),
    )
    .get();
  return retired === undefined;
}

/**
 * Swaps the workspace's slug and retires the one it replaces, in one
 * transaction. Taking `to` ends any retirement of it: the workspace's own,
 * which is the "rename back" case, and any left over from a released hold.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  from: string,
  to: string,
): Promise<Organization> {
  const stamp = toIsoTimestamp(new Date());

  return getDb().transaction((tx) => {
    tx.delete(organizationSlugRetirements)
      .where(eq(organizationSlugRetirements.slug, to))
      .run();

    tx.insert(organizationSlugRetirements)
