/**
 * Changes the workspace's URL slug. The slug is taken as typed, never
 * suffixed: an unavailable slug is refused. The old slug is retired for
 * `ORG_SLUG_HOLD_DAYS` (ADR 0005). Renaming to the current slug changes and
 * publishes nothing.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (org.slug === input.slug) return org;

  assertValidSlug(input.slug);
  if (!(await orgRepo.isOrgSlugAvailable(input.slug, input.orgId))) {
    throw new InvalidSlugError(input.slug, "is not available");
  }

  const renamed = await orgRepo.renameOrgSlug(input.orgId, org.slug, input.slug);

  await emit("organization.slug_changed", {
    ...envelope(input.orgId, actor.userId),
    from: org.slug,
    to: renamed.slug,
  });

  await record(input.orgId, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: renamed.id,
    projectId: null,
    summary: `Workspace URL changed from ${org.slug} to ${renamed.slug}`,
    metadata: { from: org.slug, to: renamed.slug },
  });

  return renamed;
}

