import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe } from "@/lib/event-bus";
import * as orgService from "@/server/services/organization-service";
import * as orgRepo from "@/server/repositories/organization-repository";
import { getDb } from "@/server/db";
import { organizationSlugRetirements } from "@/server/db/schema/organizations";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

describe("tmp rename", () => {
  it("renames, holds, releases, chains", async () => {
    const t = await createTenant("tmp-rename", "growth");
    const events: unknown[] = [];
    const off = subscribe("organization.slug_changed", (p) => { events.push(p); });
    const oldSlug = t.org.slug;
    const same = await orgService.renameOrganizationSlug(t.actors.owner, { orgId: t.org.id, slug: oldSlug });
    expect(same.slug).toBe(oldSlug);
    expect(events.length).toBe(0);
    const r = await orgService.renameOrganizationSlug(t.actors.owner, { orgId: t.org.id, slug: "brand-new" });
    expect(r.slug).toBe("brand-new");
    expect(events.length).toBe(1);
    expect((await orgRepo.findOrgBySlug(oldSlug))?.id).toBe(t.org.id);
    expect((await orgRepo.findOrgBySlug("brand-new"))?.id).toBe(t.org.id);
    await expect(orgService.renameOrganizationSlug(t.actors.owner, { orgId: t.org.id, slug: "northwind" })).rejects.toThrow();
    // another org cannot take retired slug
    const other = await createTenant("tmp-other", "growth");
    await expect(orgService.renameOrganizationSlug(other.actors.owner, { orgId: other.org.id, slug: oldSlug })).rejects.toThrow(/not available/);
    // rename back ends own retirement; then release after 30 days
    await orgService.renameOrganizationSlug(t.actors.owner, { orgId: t.org.id, slug: oldSlug });
    expect((await orgRepo.findOrgBySlug("brand-new"))?.id).toBe(t.org.id);
    await orgService.renameOrganizationSlug(t.actors.owner, { orgId: t.org.id, slug: "third-name" });
    expect((await orgRepo.findOrgBySlug(oldSlug))?.id).toBe(t.org.id);
    const rows = getDb().select().from(organizationSlugRetirements).all();
    const past = new Date(Date.now() + 30 * 24 * 3600 * 1000 + 1000);
    vi.useFakeTimers({ now: past });
    expect(await orgRepo.findOrgBySlug(oldSlug)).toBeNull();
    expect(await orgRepo.findOrgBySlug("brand-new")).toBeNull();
    expect(await orgRepo.isOrgSlugAvailable(oldSlug, other.org.id)).toBe(true);
    vi.useRealTimers();
    expect(rows.length).toBeGreaterThan(0);
    off();
  });
});
EOF
